// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_1: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.foraging-friends","name":"Foraging Friends","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Giving a cheerful whistle, you call forth a handful of small animals, such as birds or mice, to collect food for you and your allies. The animals return 1 hour later with enough foraged goods to feed four Medium creatures for 1 day, then return to their normal behavior. If you're in a particularly strange environment, as determined by your GM, you might need a minimum proficiency with primal spell DCs, equivalent to the minimum proficiency required to Subsist in strange environments.\n\nHeightened (3rd) The animals bring back enough food for eight Medium creatures for 1 day.\n\nHeightened (5th) The animals bring back enough food for 30 Medium creatures for 1 day.","source":{"provider":"PAIZO","sourceId":"qdfV4y8B6mbg4Fnm","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.forbidden-thought","name":"Forbidden Thought","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","mental","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"xmlng4v8ws11x8cn","formula":"2d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"xmlng4v8ws11x8cn":"1d6"}},"counteraction":false,"ritual":null,"description":"You place a psychic lock in a foe's mind that prevents it from a specific action. Choose \"Strike,\" \"Stride,\" \"Cast a Spell,\" or a specific action you know the creature to have (such as a dragon's magic breath). If the creature attempts that action on its next turn, it must surmount your lock to do so, causing it to take 2d6 mental damage (with a basic Will save). The target is then temporarily immune for 1 minute.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"lpoWfblSMLcJfxsZ","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.forbidding-ward","name":"Forbidding Ward","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 ally and 1 enemy","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ward an ally against the attacks and hostile spells from the target enemy. The target ally gains a +1 status bonus to Armor Class and saving throws against the target enemy's attacks, spells, and other effects.\n\nHeightened (6th) The status bonus increases to +2.","source":{"provider":"PAIZO","sourceId":"RA7VKcen3p56rVyZ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.force-barrage","name":"Force Barrage","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d4+1","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fire a shard of solidified magic toward a creature that you can see. It automatically hits and deals 1d4+1 force damage. For each additional action you use when Casting the Spell, increase the number of shards you shoot by one, to a maximum of three shards for 3 actions. You choose the target for each shard individually. If you shoot more than one shard at the same target, combine the damage before applying bonuses or penalties to damage, resistances, weaknesses, and so forth.\n\nHeightened (+2) You fire one additional shard with each action you spend.","source":{"provider":"PAIZO","sourceId":"gKKqvLohtrSJj3BM","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.force-bolt","name":"Force Bolt","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","force","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d4+1","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d4+1"}},"counteraction":false,"ritual":null,"description":"You fire an arrow-shaped bolt of force, one of the most common and reliable forms of battle magic. It automatically hits and deals 1d4+1 force damage to the target.\n\nHeightened (+2) The damage increases by 1d4+1.","source":{"provider":"PAIZO","sourceId":"Hu38hoAUSYeFpkVa","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.force-fang","name":"Force Fang","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","force","magus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d4+1","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d4+1"}},"counteraction":false,"ritual":null,"description":"You briefly turn your attack into pure force to bypass your opponent's defenses. Choose a target within your reach, or within the reach of a melee weapon you're wielding. If you can use with a ranged weapon (with the starlit span hybrid study, for example), you can target a creature in the first range increment of your ranged weapon. For an instant, you transform your weapon or unarmed attack into a spike of pure force, replacing all its normal statistics and abilities. The force fang automatically deals 1d4+1 force damage to the target.\n\nHeightened (+2) The damage increases by 1d4+1.","source":{"provider":"PAIZO","sourceId":"9mPEoOPN0AMuixIv","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.forced-mercy","name":"Forced Mercy","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You soften the target's blows, ensuring they avoid vital areas and cause no lasting harm. All physical damage dealt by the target to living creatures becomes nonlethal and all persistent bleed damage dealt by the target is reduced to 0. This effect doesn't incur the typical –2 circumstance penalty for nonlethal attacks with a lethal weapon or attack. An unwilling target must attempt a Will save. A willing target can choose to critically fail their saving throw.\nCritical Success The creature is unaffected.\n\nSuccess The creature is affected for 1 round.\n\nFailure The creature is affected for [[/gmr 1d4 #rounds]]{1d4 rounds}.\n\nCritical Failure The creature is affected for 1 minute.\nHeightened (4th) The range increases to 100 feet, and you can target up to 8 creatures.","source":{"provider":"PAIZO","sourceId":"BQMEaeJiEFC1nepg","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.forced-quiet","name":"Forced Quiet","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You quiet the target's voice, preventing it from giving away valuable secrets. This doesn't prevent the target from talking or providing verbal spell components, but no creature more than 10 feet away can hear its whispers without succeeding at a Perception check against your spell DC, which might interfere with auditory or linguistic effects as well as communication. The spell's duration depends on the target's Fortitude save. After attempting its save, the target becomes temporarily immune for 24 hours.\n\nCritical Success The target is unaffected.\n\nSuccess The duration is 1 round.\n\nFailure The duration is 1 minute.\n\nCritical Failure The duration is 10 minutes.","source":{"provider":"PAIZO","sourceId":"k43PIYwuQqjeJ3S3","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.forge","name":"Forge","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["fire"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature or unattended metal object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"ugQLPWwEq70gVBNG","formula":"3d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"ugQLPWwEq70gVBNG":"2d6"}},"counteraction":false,"ritual":null,"description":"Developed before the introduction of the Iron Lagoon, this cantrip for superheating metal has also found valuable combat use. You superheat the target, dealing 3d6 fire damage. If the target is a metal object, reduce its Hardness by an amount equal to the damage dealt until the end of your next turn.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage.\n\nCritical Failure The target takes double damage, and if it's a metal creature, it gains weakness 2 to physical damage until the end of your next turn.\n\nHeightened (+1) The damage increases by 2d6, and the weakness on a critical failure increases by 2.","source":{"provider":"PAIZO","sourceId":"FTR8m4qrhYzTRyrD","book":"Pathfinder Lost Omens Highhelm","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fortify-summoning","name":"Fortify Summoning","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature you summoned","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"As you call a creature to your side, your magic transforms its body, heightening its ferocity and fortifying its resilience. The target gains a +1 status bonus to all checks and DCs (including its AC) for the duration of its summoning, up to 1 minute.","source":{"provider":"PAIZO","sourceId":"tWzxuJdbXqvskdIo","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.frenzied-revelry","name":"Frenzied Revelry","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cleric","concentrate","emotion","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"you and allies in the area","area":{"shape":"EMANATION","feet":5}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You recall memories of hedonistic rites to send yourself into an infectious frenzy, dancing and howling wildly to encourage your companions to join in. You and your allies gain a +1 status bonus to saving throws against mental effects while in the area. Whenever someone benefiting from this bonus critically succeeds at a saving throw against an enemy's mental effect, its revelry increases, granting it a +1 status bonus to attack rolls and damage rolls for 1 round.\n\nHeightened (4th) The emanation's radius is 10 feet, and the status bonus to saves is +2.\n\nHeightened (7th) The emanation's radius is 15 feet, and the status bonus to saves is +3.","source":{"provider":"PAIZO","sourceId":"fxRaWoeOGyi6THYH","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.friendfetch","name":"Friendfetch","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 or 2 willing creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shoot out ephemeral, telekinetic strands that drag each target directly toward you, stopping in the closest unoccupied space to you in this path. This is forced movement.","source":{"provider":"PAIZO","sourceId":"TjrZGl8z2INgf3vi","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.friendly-push","name":"Friendly Push","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You exert magical force to propel a willing creature up to 10 feet in a straight line, including upward, though if they aren't on solid ground or have another way to maintain their height (such as a fly Speed) when the movement ends, they fall. When you Sustain the spell, you can move them again or choose a new target within range and move them instead.\n\nYou can cast this spell on an ally, and if you do, the movement from this spell doesn't trigger reactions.\nHeightened (4th) The distance increases to 20 feet.\n\nHeightened (7th) The distance increases to 30 feet.","source":{"provider":"PAIZO","sourceId":"cCFDnmFB1EGeQUeA","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.frosts-touch","name":"Frost's Touch","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cantrip","cold","concentrate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your gelid shard drinks down nearby heat in a futile attempt to sate itself and achieve a level of frigid cold unheard of in the Universe. This allows you to cool a drink, make a hot pot safe to handle, or other, similar minor effects. Once cooled, the object's temperature is subject to its environment as usual. You can also solidify ambient moisture into a solid object; this temporary object is of negligible Bulk, made of non-magical ice. The object looks crude and artificial and is extremely fragile—it can't be used as a tool, weapon, or locus or cost for a spell. Once created, it melts as normal for ice for the ambient conditions.\nHeightened (3rd) You can create simple objects of ice with up to 1 Bulk and of a level not exceeding 1. Such objects must be rigid. You can only have one such object created at a time; if you create another, the previous object melts instantly.\n\nHeightened (5th) Items you create can be up to 4 Bulk and 4th level.\n\nHeightened (7th) Items you create can be up to 8 Bulk and 8th level.\n\nHeightened (9th) Items you create can be up to 20 Bulk and 12th level.","source":{"provider":"PAIZO","sourceId":"WFSazGLCUuPsBv1p","book":"Pathfinder Treasure Vault (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.frostbite","name":"Frostbite","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"3bsJUDEgedKhPx6T","formula":"2d4","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"3bsJUDEgedKhPx6T":"1d4"}},"counteraction":false,"ritual":null,"description":"An orb of biting cold coalesces around your target, freezing its body. The target takes 2d4 cold damage with a basic Fortitude save. On a critical failure, the target also gains weakness 1 to bludgeoning until the start of your next turn.\n\nHeightened (+1) The damage increases by 1d4 and the weakness on a critical failure increases by 1.","source":{"provider":"PAIZO","sourceId":"IxhGEKl63R4QBvkj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.funeral-flames","name":"Funeral Flames","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","fire","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"one club or staff you're wielding","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform a bludgeon into a fearsome torch suited to casting undead into the afterlife. One end of the weapon ignites, becoming wreathed in blue flame. While you wield the target weapon, it becomes a +1 weapon, gains the versatile fire trait, and sheds light as brightly as a torch. Whenever you successfully Strike a creature with the weapon, you can Dismiss the spell as a free action to deal 1d6 persistent fire damage to the target; if the target is undead, increase the persistent damage dice to d8s.\n\nHeightened (+2) The persistent fire damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"5KmyO4YSGEAUdgAS","book":"Pathfinder #216: The Acropolis Pyre","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gale-blast","name":"Gale Blast","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["air","cantrip","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"1d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Wind flows from your outstretched hands and whirls around you in a 5-foot emanation. Each creature in the area takes 1d6 bludgeoning damage, with a Fortitude save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is pushed 5 feet away from you.\n\nCritical Failure The creature takes double damage and is pushed 10 feet away from you.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"dDiOnjcsBFbAvP6t","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.garden-of-healing","name":"Garden of Healing","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","aura","emotion","focus","healing","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"J1hHMzwleLLa292j","formula":"1d4","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"J1hHMzwleLLa292j":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Spirits of comfort and respite swirl around you, trailing visions of growing grass and blooming blossoms. When you cast this spell and the first time you Sustain it on each subsequent round, you generate a pulse of renewing energy that heals each creature within the emanation for 1d4 Hit Points. The calm of this effect lingers; once this spell ends, any creature that has been affected by its healing gains a +1 circumstance bonus to saves against emotion effects for 10 minutes but does not receive any healing from additional castings of the spell while the bonus persists.\n\nHeightened (+1) The healing granted by the spell's pulse increases by 1d4 Hit Points.","source":{"provider":"PAIZO","sourceId":"w4M6Vqvq8k6MOFvj","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.genies-veil","name":"Genie's Veil","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range is attacked.\n\nWith a flourish, you fulfill a creature's wish for protection, bending reality to keep them from harm. The target vanishes in a burst of brightly colored smoke and sparkles, reappearing an instant later. They become against the triggering attack and until the end of the current creature's turn.","source":{"provider":"PAIZO","sourceId":"OyiKIbWllLZC6sGz","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gentle-landing","name":"Gentle Landing","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["air","concentrate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 falling creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger a creature within range is falling\n\nYou raise a magical updraft to arrest a fall. The target's fall slows to 60 feet per round, and the portion of the fall during the spell's duration doesn't count when calculating falling damage. If the target reaches the ground while the spell is in effect, it takes no damage from the fall. The spell ends as soon as the target lands.","source":{"provider":"PAIZO","sourceId":"TTwOKGqmZeKSyNMH","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ghost-sound","name":"Ghost Sound","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","cantrip","concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create an auditory illusion of simple sounds that has a maximum volume equal to four normal humans shouting. The sounds emanate from a square you designate within range. You can't create intelligible words or other intricate sounds (such as music).\n\nHeightened (3rd) The range increases to 60 feet.\n\nHeightened (5th) The range increases to 120 feet.","source":{"provider":"PAIZO","sourceId":"atlgGNI1E1Ox3O3a","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gift-of-the-anemos","name":"Gift of the Anemos","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["air","animist","aura","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your apparition envelops you in gusting winds that can speed your steps or buffet your foes. When an enemy in the aura critically fails a Strike against you, they must succeed at a Reflex save or become until the end of your next turn. When you cast or sustain this spell, you can either Step, a creature in the aura using your spell attack modifier in place of your Athletics modifier, or jump 10 feet in any direction (you must land on solid ground, or else you fall).","source":{"provider":"PAIZO","sourceId":"x2Gf3lt64eoMocMd","book":"Pathfinder #216: The Acropolis Pyre","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.glamorize","name":"Glamorize","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Using simple magical gestures, you alter a minor detail of your appearance (add or remove highlights to your hair color, apply or remove cosmetics, add polish or accessories to your nails, etc.) or create a small environmental effect that's confined to your person (adjust surrounding lighting to favor your good side, cause a brief wind to make your hair blow dramatically, make a small chime occur as you smile, etc.). While the spell is active, you can Sustain it to make further adjustments. The changes persist until the spell's duration ends.\n\nAt the GM's discretion, such alterations might grant a +1 status bonus to certain tasks, such as Impersonate or .","source":{"provider":"PAIZO","sourceId":"UK349cSOljQVYpcu","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.glass-shield","name":"Glass Shield","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","earth"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"dtpQLfwMi5qU2XEa","formula":"1d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You summon a layer of clear glass to keep you from harm. This counts as using the action, giving you a +1 circumstance bonus to AC until the start of your next turn, but it doesn't require a hand to use. You can with the glass shield. It has Hardness 2. You can use the spell's reaction to reduce damage from any spell or magical effect, even if it doesn't deal physical damage. When you Shield Block, the shield explodes in a shower of glass. If creature that broke it is within 5 feet, the shards deal 1d4 piercing damage to that creature with a basic Reflex save. After you use Shield Block, the spell ends and you can't cast it again for 10 minutes.\n\nHeightened (3rd) The shield has Hardness 4, and the damage increases to 3d4.\n\nHeightened (5th) The shield has Hardness 7, and the damage increases to 4d4.\n\nHeightened (7th) The shield has Hardness 10, and the damage increases to 5d4.\n\nHeightened (9th) The shield has Hardness 12, and the damage increases to 6d4.","source":{"provider":"PAIZO","sourceId":"cgfl9Qr46bKaA59e","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.glimpse-weakness","name":"Glimpse Weakness","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You glimpse a loose scale, a seam in a foe's armor, or a similar weakness, aiding your allies in landing a precise hit. The first ally that hits the target with a successful Strike deals additional precision damage equal to 1 + this spell's rank, and then the spell ends.","source":{"provider":"PAIZO","sourceId":"cNnHV97gPqxJ3Rrr","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.glowing-trail","name":"Glowing Trail","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your movements leave a vague glowing path behind you, like a misty echo of your presence. While your form is not discernible, your size is. This path hangs in space and is not anchored to any surface, so it tracks your movement through the air. The path fades after 10 minutes. You can Dismiss this spell at any time, but the path fades normally. The path can be visible or . While visible, it appears as a faintly glowing mist in a color of your choosing but sheds no light beyond its area. While invisible, you can still detect the path, but it gives off no light.\n\nHeightened (3rd) The glowing trail fades after 1 day.\n\nHeightened (5th) The glowing trail fades after 1 week.\n\nHeightened (7th) The glowing trail fades after 1 month.\n\nHeightened (9th) The glowing trail fades after 1 year.","source":{"provider":"PAIZO","sourceId":"m1vKX4xxWQJXfupu","book":"Pathfinder #194: Cult of the Cave Worm","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gluttons-jaws","name":"Glutton's Jaws","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"GUwgkd9LwISbTZDb","formula":"2d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"GUwgkd9LwISbTZDb":"2d6"}},"counteraction":false,"ritual":null,"description":"A slavering maw opens beneath a target and tries to take a bite out of them. Make a spell attack roll. On a hit, the mouth deals 2d6 piercing damage, and you gain 1d4 temporary Hit Points that last until the beginning of your next turn.\n\nHeightened (+1) The damage increases by 2d6, and the temporary Hit Points increase by 1d4.","source":{"provider":"PAIZO","sourceId":"SdXFiQ4Py8761sNO","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.goblin-pox","name":"Goblin Pox","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","disease","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your touch afflicts the target with goblin pox, an irritating allergenic rash. The target must attempt a Fortitude save.\n\nGoblin Pox (disease) Level 1; Creatures that have the goblin trait and goblin dogs are immune\n\nStage 1 Sickened 1 (1 round)\n\nStage 2 Sickened 1 and Slowed 1 (1 round)\n\nStage 3 Sickened 1 and the creature can't reduce its Sickened value below 1 (1 day)\n\nCritical Success The target is unaffected.\n\nSuccess The target is Sickened 1.\n\nFailure The target is afflicted with goblin pox at stage 1.\n\nCritical Failure The target is afflicted with goblin pox at stage 2.","source":{"provider":"PAIZO","sourceId":"zJQnkKEKbJqGB3iB","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gouging-claw","name":"Gouging Claw","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","cantrip","concentrate","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false},{"id":"3Pz4NTLXD2rzKgf4","formula":"2","damageType":"bleed","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","3Pz4NTLXD2rzKgf4":"1"}},"counteraction":false,"ritual":null,"description":"You temporarily morph your limb into a clawed appendage. Make a melee spell attack roll against your target's AC. If you hit, you deal your choice of 2d6 slashing damage or 2d6 piercing damage, plus 2 persistent bleed damage. On a critical success, you deal double damage and double bleed damage.\nHeightened (+1) The damage increases by 1d6 and the persistent bleed damage increases by 1.","source":{"provider":"PAIZO","sourceId":"MPxbKoR54gkYkqLO","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.grasping-vine","name":"Grasping Vine","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","plant","wizard","wood"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 unattended object of up to 8 Bulk, or Medium or smaller creature that is currently on the ground","area":null},"duration":{"text":"1 minute (see text)","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A thick, curling vine erupts from the ground beneath you and stretches to the target, allowing you to move it around. If the target is an item, you can move it 10 feet in any direction within range when you Cast the Spell and the first time you Sustain it each round. If the target is a creature, they must attempt a Reflex save.\nCritical Success The target is unaffected and the spell ends.\n\nSuccess The target is until the end of your next turn unless it Escapes (the vine's DC is equal to your spell DC) or destroys the vine (the vine has AC 15 and 10 Hit Points), at which point the spell ends.\n\nFailure The target is grabbed until it Escapes or destroys the vine, at which point the spell ends. The first time each round you Sustain this spell, you can the grabbed target up to 5 feet.\n\nCritical Failure As failure, and you can immediately Reposition the target up to 10 feet.","source":{"provider":"PAIZO","sourceId":"cQgPIohUja0DUiRL","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gravitational-pull","name":"Gravitational Pull","kind":"SPELL","rank":1,"rarity":"COMMON","traits":[],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"By suddenly altering gravity, you pull the target toward you. The target is pulled 10 feet closer to you unless it succeeds at a Fortitude save. On a critical failure, it's also knocked . The effects of this spell change depending on the number of actions you spend when you Cast this Spell.\n\n1 (somatic) The spell targets one creature.\n\n2 (somatic, verbal) The spell targets one creature and pulls the target 20 feet instead of 10.\n\n3 (material, somatic, verbal) The spell targets up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"F1fQC9SarAkjNxpP","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gravity-weapon","name":"Gravity Weapon","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You build up gravitational force and funnel it into your blows, leading to more powerful attacks with blade and bow alike. On your first weapon Strike each round, you gain a status bonus to damage equal to twice the number of weapon damage dice.","source":{"provider":"PAIZO","sourceId":"IWUe32Y5k2QFd7YQ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.grease","name":"Grease","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 object of Bulk 1 or less","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure grease, choosing an area or target.\n\n- Area [4 contiguous 5-foot squares] All solid ground in the area is covered with grease. Each creature standing on the greasy surface must succeed at a Reflex save or an Acrobatics check against your spell DC or fall . Creatures using an action to move onto the greasy surface during the spell's duration must attempt either a Reflex save or an Acrobatics check to . A creature that Steps or Crawls doesn't have to attempt a check or save.\n\n- Target [1 object of Bulk 1 or less] If you Cast the Spell on an unattended object, anyone trying to pick up the object must succeed at an Acrobatics check or Reflex save against your spell DC to do so. If you target an attended object, the creature that has the object must attempt an Acrobatics check or Reflex save. On a failure, the holder or wielder takes a –2 circumstance penalty to all checks that involve using the object; on a critical failure, the holder or wielder releases the item. The object lands in an adjacent square of the GM's choice. If you Cast this Spell on a worn object, the wearer gains a +2 circumstance bonus to Fortitude saves against attempts to grapple them.","source":{"provider":"PAIZO","sourceId":"Wu0xFpewMKRK3HG8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.grim-tendrils","name":"Grim Tendrils","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d4","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"}},"counteraction":false,"ritual":null,"description":"Tendrils of darkness curl out from your fingertips and race through the air. You deal 2d4 void damage and (@item.level)[bleed] damage to living creatures in the line. Each living creature in the line must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half the void damage and no persistent bleed damage.\n\nFailure The creature takes full damage.\n\nCritical Failure The creature takes double void damage and double persistent bleed damage.\n\nHeightened (+1) The void damage increases by 2d4, and the persistent bleed damage increases by 1.","source":{"provider":"PAIZO","sourceId":"k34hDOfIIMAxNL4a","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.gritty-wheeze","name":"Gritty Wheeze","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["air","concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"en43qsw1luwagcht","formula":"2d4","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"en43qsw1luwagcht":"2d4"}},"counteraction":false,"ritual":null,"description":"You exhale desiccating grit and sand in a small cloud. Creatures in the area take 2d4 bludgeoning damage and must attempt a Fortitude save.\n\nWater creatures and plant creatures use the outcome one degree of success worse than the result of their saving throw.\n\nCritical Success The creature takes no damage.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is for 1 round.\n\nCritical Failure The creature takes double damage and is dazzled for 1 minute.\n\nHeightened (+1) The damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"s8gTmnNMg4H4bHEF","book":"Pathfinder Adventure: Threshold of Knowledge","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.guidance","name":"Guidance","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ask for the guidance of supernatural entities, granting the target a +1 status bonus to one attack roll, Perception check, saving throw, or skill check the target attempts before the duration ends. The target chooses which roll to use the bonus on before rolling. If the target uses the bonus, the spell ends. Either way, the target is then temporarily immune for 1 hour.","source":{"provider":"PAIZO","sourceId":"izcxFQFwf3woCnFs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.guided-introspection","name":"Guided Introspection","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You guide the target in examining their innermost feelings, their behaviors, and the motivations behind their actions, granting them clarity and insight. The target gains a +1 status bonus to saving throws against emotion and fear.\n\nIf the target would become during the spell's duration, they reduce the duration of the confused condition by 1 round, to a minimum of 1 round. If the target would become or , they reduce the value of the frightened or stupefied condition by 1, to a minimum of 1. Once any of these conditions occur, the spell ends.\nHeightened (4th) The status bonus increases to +2.","source":{"provider":"PAIZO","sourceId":"R569jdqpNry8m0TJ","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.gust-of-wind","name":"Gust of Wind","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"C34n7XTpCLCXJWwt","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A violent wind issues forth from your palm, blowing from the point where you are when you Cast the Spell to the line's opposite end. The wind extinguishes small non-magical fires, disperses fog and mist, blows objects of light Bulk or less around, and pushes larger objects. Large or smaller creatures in the area must attempt a Fortitude save. Large or smaller creatures that later move into the gust must attempt the save on entering.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature can't move against the wind.\n\nFailure The creature is knocked . If it was flying, it takes the effects of critical failure instead.\n\nCritical Failure The creature is pushed 30 feet in the wind's direction, knocked prone, and takes 2d6 bludgeoning damage.","source":{"provider":"PAIZO","sourceId":"g8QqHpv2CWDwmIm1","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.halcyon-mists","name":"Halcyon Mists","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","water"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"In a moment of dire need, you call upon ancestral power to strengthen and sustain. A soothing mist gathers around the target, granting 1d8 temporary Hit Points and ending one source of persistent acid, bleed, fire, poison, or void damage affecting it. If the creature has persistent damage from more than one of these sources, you choose the one that ends.\n\nThe mists linger around the target, making them until the beginning of their next turn, though this obvious concealment can't be used to Hide.\nHeightened (+1) The temporary Hit Points increase by 1d8.","source":{"provider":"PAIZO","sourceId":"IERHT6v4o5ISvuJG","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hallowed-ground","name":"Hallowed Ground","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","good","holy","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d6","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1d4","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6","1":"1d4"}},"counteraction":true,"ritual":null,"description":"One small space becomes inhospitable to undead as you fill it with life-infused benevolent magic. Each undead creature in the area takes 1d6 vitality damage and 1d4 spirit damage when you Cast the Spell, with a basic Fortitude save. After that, undead creatures have weakness 1 to vitality damage and your necromancy spells while in the area.\n\nThis spell also automatically attempts to counteract any attempt to raise undead in the area (if either the undead would appear in the area or the effect's caster or creator is in it).\n\nIf you Cast this Spell again, any previous hallowed ground you had cast ends.\n\nHeightened (+2) The vitality damage increases by 1d6, spirit damage increases by 1d4, and weakness increases by 1.","source":{"provider":"PAIZO","sourceId":"4bFxUA59xeq6Snhw","book":"Pathfinder Book of the Dead","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.hand-of-the-apprentice","name":"Hand of the Apprentice","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take advantage of one of the most fundamental lessons of magic to levitate and propel your weapon. You hurl a held melee weapon with which you are trained at the target, making a spell attack roll. On a success, you deal the weapon's damage as if you had hit with a melee Strike, but adding your spellcasting ability modifier to damage, rather than your Strength modifier. On a critical success, you deal double damage, and you add the weapon's critical specialization effect. Regardless of the outcome, the weapon flies back to you and returns to your hand.","source":{"provider":"PAIZO","sourceId":"bSDTWUIvgXkBaEv8","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.harm","name":"Harm","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["manipulate","void"],"traditions":["DIVINE"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 living creature or 1 willing undead creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d8","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You channel void energy to harm the living or heal the undead. If the target is a living creature, you deal 1d8 void damage to it, and it gets a basic Fortitude save. If the target is a willing undead creature, you restore that amount of Hit Points. The number of actions you spend when Casting this Spell determines its targets, range, area, and other parameters.\n\n1 The spell has a range of touch.\n\n2 (concentrate) The spell has a range of 30 feet. If you're healing an undead creature, increase the Hit Points restored by 8.\n\n3 (concentrate) You disperse void energy in a . This targets all living and undead creatures in the area.\n\nHeightened (+1) The amount of healing or damage increases by 1d8, and the extra healing for the 2-action version increases by 8.","source":{"provider":"PAIZO","sourceId":"wdA52JJnsuQWeyqz","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.harrowing","name":"Harrowing","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":["fortune"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"rare pigments and inks worth a total value of 20 gp × the target's level"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 month or until fulfilled","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Fortune-Telling Lore (trained) or Occultism (expert)","secondaryCasters":0},"description":"The typical harrow reading does not magically manipulate fate, but when you perform a harrowing ritual to infuse a reading with occult power, you can impart real magical benefits to the target of the reading that give them agency and control over a task or goal in their immediate future. The first 50 minutes of this ritual's casting are spent preparing the target creature for the reading by meditating, concentrating on the task or goal to be focused on, and allowing you to paint or ink occult symbols from the harrow onto the target's body to link them to the upcoming reading. The final 10 minutes of the ritual comprise the reading itself, during which the symbols placed on the target fade away while infusing their fate.\n\nThe target of harrowing must describe a set of events or course of action they intend to attempt in the near future—something like \"hunting down a specific wanted criminal\" or \"traveling to Varisia to investigate the Storval Stairs.\" You can roleplay out the actual harrow reading if you wish, using any spread to perform the reading, but at the ritual's completion, a single potential opportunity for the target to manipulate fate bonds to their destiny, depending on the result of your primary skill check to perform this ritual.\n\nAs long as this ritual's duration persists, the creature is temporarily immune to further harrowing rituals.\n\nCritical Success The target gains agency over fate and chance while in the pursuit of their goal, gaining a \"wild card.\" Randomly determine a harrow suit, either by rolling 1d6 or by drawing a card from a full harrow deck, and then consult the Associated Suit Checks table below. At any point during harrowing's duration, the creature can expend this wild card to immediately reroll any associated check they just made, gaining a +4 status bonus to the reroll. They must use the second result. Once this reroll is taken and the wild card is spent, the harrowing ritual's effects end.\n\nSuccess As critical success, but the wild card does not grant a status bonus to the reroll.\n\nFailure As success, but the wild card instead grants a –4 status penalty to the reroll.\n\nCritical Failure The target's destiny is beyond their capability to manipulate. The wild card has no effect, and further harrowing rituals cast on the target for one month automatically result in critical failures.\n\nHeightened (+1) The target gains an additional wild card. Attempt a primary skill check for each additional wild card drawn to determine that card's benefits. The harrowing's duration ends as soon as the target spends all of their wild cards.\n\nSuit\nAssociated Check\n\n1—Hammers (Str)\nStrikes (both melee and ranged)\n\n2—Keys (Dex)\nReflex saving throws\n\n3—Shields (Con)\nFortitude saving throws\n\n4—Books (Int)\nSkill checks\n\n5—Stars (Wis)\nWill saving throws\n\n6—Crowns (Cha)\nAll other checks (including flat checks)","source":{"provider":"PAIZO","sourceId":"ofAQyLtLEGnOIs3N","book":"Pathfinder Stolen Fate Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.haunting-hymn","name":"Haunting Hymn","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","cantrip","concentrate","manipulate","sonic"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d8","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You echo a jarring hymn that only creatures in the area can hear. The hymn deals 1d8 sonic damage, with a basic Fortitude save. If a target critically fails the save, it's also for 1 minute.\n\nHeightened (+2) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"b5BQbwmuBhgPXTyi","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.heal","name":"Heal","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 willing living creature or 1 undead","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d8","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You channel vital energy to heal the living or damage the undead. If the target is a willing living creature, you restore 1d8 Hit Points. If the target is undead, you deal that amount of vitality damage to it, and it gets a basic Fortitude save. The number of actions you spend when Casting this Spell determines its targets, range, area, and other parameters.\n\n1 The spell has a range of touch.\n\n2 (concentrate) The spell has a range of 30 feet. If you're healing a living creature, increase the Hit Points restored by 8.\n\n3 (concentrate) You disperse vital energy in a . This targets all living and undead creatures in the burst.\n\nHeightened (+1) The amount of healing or damage increases by 1d8, and the extra healing for the 2-action version increases by 8.","source":{"provider":"PAIZO","sourceId":"rfZpqmj0AIIdkVIs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.heal-animal","name":"Heal Animal","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["druid","focus","healing","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 or 2"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 willing living animal","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You heal an animal's wounds, restoring 1d8 Hit Points to the target. The number of actions spent Casting this Spell determines its effect.\n\n1 The spell has a range of touch.\n\n2 (concentrate) The spell has a range of 30 feet and restores an additional 8 Hit Points to the target.\n\nHeightened (+1) The amount of healing increases by 1d8, and the additional healing for the 2-action version increases by 8.","source":{"provider":"PAIZO","sourceId":"Zmh4ynfnCtwKeAYl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.heal-companion","name":"Heal Companion","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","healing","ranger","vitality"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 or 2"}},"targeting":{"range":{"kind":"TEXT","text":"touch or 30 feet"},"target":"your animal companion","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d10","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"}},"counteraction":false,"ritual":null,"description":"You heal your animal companion's wounds. You restore 1d10 Hit Points to your animal companion. The number of actions you spend Casting this Spell determines range and other parameters.\n\n1 (manipulate) The spell has a range of touch.\n\n2 (concentrate, manipulate) The spell has a range of 30 feet and restores an additional 8 Hit Points to the target.\n\nHeightened (+1) The amount of healing increases by 1d10, and the additional healing for the 2-action version increases by 8.","source":{"provider":"PAIZO","sourceId":"KIV2LqzS5KtqOItV","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.healers-blessing","name":"Healer's Blessing","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing living creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your words bless a creature with an enhanced connection to vital energy. When the target regains Hit Points from a healing vitality spell, it regains 2 additional Hit Points.\n\nThe target regains additional Hit Points from healer's blessing only the first time it regains HP from a given healing spell, so a spell that heals the creature repeatedly over a duration would restore additional Hit Points only once, when they are first healed.\n\nHeightened (+1) The additional healing increases by 2 HP.","source":{"provider":"PAIZO","sourceId":"rhJyqB9g3ziImQgM","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.healing-plaster","name":"Healing Plaster","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","earth","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":5},"target":"a handful of dirt or mud","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You purify some dirt or mud into a pliable, claylike plaster that can aid in clotting and healing. This restorative substance can be used in lieu of healer's tools for Medicine checks to Administer First Aid or Treat Wounds. If the plaster isn't used within the spell's duration, or if you Cast the Spell again before using the plaster, it reverts to being normal non-magical earth.\n\nHeightened (3rd) The plaster grants anyone using it to Administer First Aid or Treat Wounds a +1 item bonus to the Medicine check.","source":{"provider":"PAIZO","sourceId":"m5QS8q5M6K0euKcT","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hearts-hook","name":"Heart's Hook","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","emotion","focus","manipulate","mental","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"two creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You drive two creatures toward a fated meeting. Each will be compelled toward the other, but you can elect to have one automatically succeed on its saving throw.\nSuccess The creature is unaffected.\n\nFailure The creature must spend the first action on its next turn to approach its partner. It can't Delay or take any reactions until it has obeyed this urge.\n\nCritical Failure As failure, but the target must use all its actions on its next turn.","source":{"provider":"PAIZO","sourceId":"1B8BLEQBQn9aEMoY","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.helpful-steps","name":"Helpful Steps","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth a ladder or staircase to help you reach greater heights. The ladder or staircase appears in a space you designate and either stands freely or connects to a nearby wall if possible. You decide the height of the ladder or staircase when casting the spell, up to a maximum height of 40 feet. The ladder or staircase is locked in place and magically supported, allowing you to ascend even if it's in an open area. The conjured ladder is simple in design and made of wood. The staircase is a spiral staircase made of wood. While both are supported and have no risk of falling, they can be damaged and destroyed as normal. The staircase is typically easier to ascend, though it's less discreet than a ladder and could possibly draw more attention. You can Dismiss the spell.\n\nHeightened (+1) The maximum height increases by 40 feet.","source":{"provider":"PAIZO","sourceId":"3SJEBgXHolrSAFqD","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hippocampus-retreat","name":"Hippocampus Retreat","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","concentrate","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You're mostly or totally submerged in water."},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"iieCBku11ZoTAxtN","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"iieCBku11ZoTAxtN":"1d6"}},"counteraction":false,"ritual":null,"description":"Requirements You're mostly or totally submerged in water.\nYou temporarily shape your lower limbs into the tail of a hippocampus in order to swim away from a nearby foe after dealing a parting blow. Attempt a melee spell attack roll against the target's AC, dealing 2d6 bludgeoning damage on a hit (or double damage on a critical hit). Then, Swim up to 30 feet; if you already have a swim Speed, you can Swim up to your Speed with a +10-foot circumstance bonus. You gain a +2 circumstance bonus to your AC against reactions triggered by this movement. At the end of the movement, your lower limbs return to normal.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"wSK0wtn8iHShYT9y","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hollow-heart","name":"Hollow Heart","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cleric","concentrate","emotion","fear","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You stoke the target's ambition beyond reason, until it believes no one is capable of helping it, or that others aren't to be trusted. The target attempts a Will saving throw.\n\nCritical Success The target is unaffected.\n\nSuccess The target treats no other creature as an ally for 1 round.\n\nFailure The target treats no other creature as an ally for 3 rounds.\n\nCritical Failure As failure, and the target is Frightened 1 as it realizes it can't rely on anyone but itself.","source":{"provider":"PAIZO","sourceId":"k6f5nvSv0XIhbiHj","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.home-among-mulberry-leaves","name":"Home Among Mulberry Leaves","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","magus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1},"requirements":"You're wielding qi-infused fabric."},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Requirements You're wielding qi-infused fabric.\nQi-formed threads unravel from your fabric on conjured needles as your attack makes contact with an enemy and wraps it in place like an insect in its cocoon. Make a melee Strike with your qi-infused fabric. On a success, the target is until the start of your next turn, though it can attempt to against your spell DC. On a critical success, your needles anchor in the target's nerve centers after the threads bind it, making it your choice of Clumsy 1 or Enfeebled 1 until the start of your next turn, in addition to immobilizing it.","source":{"provider":"PAIZO","sourceId":"JIphJbkWHndtFk72","book":"Pathfinder Lost Omens Tian Xia Character Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.horizon-thunder-sphere","name":"Horizon Thunder Sphere","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","concentrate","electricity","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"2 to 2 rounds"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You gather magical energy into your palm, forming a concentrated ball of electricity that crackles and rumbles like impossibly distant thunder. Make a ranged spell attack roll against your target's AC. On a success, you deal 3d6 electricity damage. On a critical success, the target takes double damage and is for 1 round. The number of actions you spend when Casting this Spell determines the range and other parameters.\n\n2 This spell has a range of 30 feet.\n\n3 This spell has a range of 60 feet and deals half damage on a failure (but not a critical failure) as the electricity lashes out and jolts the target.\n\nTwo Rounds If you spend 3 actions Casting the Spell, you can avoid finishing the spell and spend another 3 actions on your next turn to empower the spell even further. If you do, after attacking the target, whether you hit or miss, the ball of lightning explodes, dealing (@item.rank*2)d6[electricity] damage to all other creatures in a around the target (basic Reflex save). Additionally, you spark with electricity for 1 minute, dealing (@item.rank)[electricity] damage to creatures that Grab you or that hit you with an unarmed Strike or a non-reach melee weapon.\n\nHeightened (+1) The initial damage on a hit, as well as the burst damage for two-round casting time, each increase by 2d6, and the damage creatures take if they Grapple or hit you while you're in your sparking state increases by 1.","source":{"provider":"PAIZO","sourceId":"8Uzc9WKqRr755S5d","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.hurtling-stone","name":"Hurtling Stone","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cleric","earth","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You evoke a magical stone and throw it, with divine guide to your aim. The stone deals 2d6 bludgeoning damage depending on your spell attack roll against the target's AC.\n\nCritical Success The target takes double damage and you can push it up to 10 feet.\n\nSuccess The target takes full damage and you can push it up to 5 feet.\n\nHeightened (+1) The stone's damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"pRKaEXnjGJXbPHPC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hydraulic-push","name":"Hydraulic Push","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature or unattended object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You call forth a powerful blast of pressurized water that bludgeons the target and knocks it back. Make a ranged spell attack roll.\n\nCritical Success The target takes 6d6 bludgeoning damage and is knocked back 10 feet.\n\nSuccess The target takes 3d6 bludgeoning damage and is knocked back 5 feet.\n\nHeightened (+1) The bludgeoning damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"jfVCuOpzC6mUrf6f","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.hymn-of-healing","name":"Hymn of Healing","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","focus","healing","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you or 1 ally","area":null},"duration":{"text":"4 rounds","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your glorious singing mends wounds and provides a temporary respite from harm. The target gains fast healing 2. When you Cast the Spell and the first time each round you Sustain the Spell, the target gains 2 temporary Hit Points, which last for 1 round.\n\nHeightened (+1) The fast healing and temporary Hit Points each increase by 2.","source":{"provider":"PAIZO","sourceId":"gSUQlTDYoLDGAsCP","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ignite-ambition","name":"Ignite Ambition","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","emotion","focus","mental","subtle"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"one creature being influenced","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or an ally in range attempt to use a mental effect to convince a creature to do something (such as a , , or a spell).\n\nYou strengthen a target's ambition, increase its resentment of allies, and make its allegiances more susceptible to change. The target must attempt a Will save.\n\nCritical Success The target is unaffected and realized you attempted to influence its reaction with magic.\n\nSuccess The target takes a -1 status penalty to its defenses against the triggering effect. This penalty is -2 if the target is being encouraged to advance its own ambitions.The target doesn't realize you Cast the Spell on it.\n\nFailure As success, but the penalty is -4 if the target is being encouraged to advance its own ambitions.\n\nCritical Failure As success, but the creature automatically follows a suggestion that advances its own ambitions.","source":{"provider":"PAIZO","sourceId":"Dj44lViYKvOJ8a53","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ignition","name":"Ignition","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","cantrip","concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"cQDyW0QpjJ38MlSi","formula":"2d4","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"cQDyW0QpjJ38MlSi":"1d4"}},"counteraction":false,"ritual":null,"description":"You snap your fingers and point at a target, which begins to smolder. Make a spell attack roll against the target's AC, dealing 2d4 fire damage on a hit. If the target is within your melee reach, you can choose to make a melee spell attack with the flame instead of a ranged spell attack, which increases all the spell's damage dice to d6s.\nCritical Success The target takes double damage and 1d4 persistent fire damage.\n\nSuccess The target takes full damage.\nHeightened (+1) The initial damage increases by 1d4 and the persistent fire damage on a critical hit increases by 1d4.\n\n(@item.rank)d4[persistent,fire]{Scaling Persistent Fire Damage}\n\n(@item.rank)d6[persistent,fire]{Scaling Persistent Fire Damage (Melee)}","source":{"provider":"PAIZO","sourceId":"6DfLZBl8wKIV03Iq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ill-omen","name":"Ill Omen","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","curse","manipulate","misfortune"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target is struck with misfortune, which throws it off balance. The target must attempt a Will save.\n\nSuccess The target is unaffected.\n\nFailure The first time during the duration that the target attempts an attack roll or skill check, it must roll twice and use the worse result.\n\nCritical Failure Every time during the duration that the target attempts an attack roll or skill check, it must roll twice and use the worse result.","source":{"provider":"PAIZO","sourceId":"6ZIKB0151LUR19Rw","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.illuminate","name":"Illuminate","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","fire","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{},"areaFeet":10},"counteraction":false,"ritual":null,"description":"You light all non-magical light sources in the area that use fire to provide their light—such as candles, lamps, and sconces. You can choose to make the emanation smaller than its maximum, to any distance of your choice. If a light source is attended by an unwilling creature, that creature can attempt a Reflex save to snuff the light out before it becomes noticeable.\n\nHeightened (+1) The maximum area increases by 10 feet.","source":{"provider":"PAIZO","sourceId":"qCkxBOLMCCXEjBWo","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.illusory-disguise","name":"Illusory Disguise","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusion that causes the target to appear as another creature of the same body shape, and with roughly similar height (within 6 inches) and weight (within 50 pounds). The disguise is typically good enough to hide their identity, but not to impersonate a specific individual. The spell changes their appearance and voice, but not mannerisms. You can change the appearance of its clothing and worn items, such as making its armor look like a dress. Held items are unaffected, and any worn item removed from the creature returns to its true appearance.\n\nCasting illusory disguise counts as setting up a disguise for the use of Deception; it ignores any circumstance penalties the target might take for disguising itself as a dissimilar creature, gives a +4 status bonus to Deception checks to prevent others from seeing through the disguise, and lets the target add its level to such Deception checks even if untrained. You can Dismiss this spell.\n\nHeightened (3rd) The target can appear as any creature of the same size, even a specific individual. You must have seen an individual to replicate its appearance, and must have heard its voice to replicate its voice.\n\nHeightened (4th) You can target up to 10 willing creatures. If you target multiple creatures, you can choose a different disguise for each target, but none can impersonate a specific individual. You can Dismiss each disguise individually or all collectively.\n\nHeightened (7th) As 4th, but you can choose disguises that impersonate specific individuals. You must have seen an individual to replicate its appearance, and must have heard its voice to replicate its voice.","source":{"provider":"PAIZO","sourceId":"i35dpZFI7jZcRoBo","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.illusory-object","name":"Illusory Object","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":20}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusory visual image of a stationary object. The entire image must fit within the spell's area. The object appears to animate naturally, but it doesn't make sounds or generate smells. For example, water would appear to pour down an illusory waterfall, but it would be silent.\n\nAny creature that touches the image or uses the action to examine it can attempt to disbelieve your illusion.\n\nHeightened (2nd) Your image makes appropriate sounds, generates normal smells, and feels right to the touch. The spell gains the auditory and olfactory traits. The duration increases to 1 hour.\n\nHeightened (5th) As the 2nd-rank version, but the duration is unlimited.","source":{"provider":"PAIZO","sourceId":"2oH5IufzdESuYxat","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.imaginary-weapon","name":"Imaginary Weapon","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cantrip","concentrate","force","manipulate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"ky50hzqhwvdu8luq","formula":"2d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"ky50hzqhwvdu8luq":"1d6"}},"counteraction":false,"ritual":null,"description":"You create a simple weapon of force and lash out, its arc following your hand. Make a melee spell attack roll against your target's AC. If you hit, you deal 2d6 force damage. On a critical success, you deal double damage and can choose to detonate your weapon to push the target 10 feet away from you.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"sUr5KCpeE6AXfvPp","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.imprint-message","name":"Imprint Message","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You project psychic vibrations onto the target object, imprinting it with a short message or emotional theme of your design. This imprinted sensation is revealed to a creature who casts on the target object, replacing any emotional events the item was present for. If the object is in the area of a spell, the imprinted messages appear as major events in the timeline, but they don't interfere with any other visions.\n\nIf the object is targeted with of a higher spell rank than imprint message, the caster learns that the object has been magically modified. When you Cast this Spell, any prior vibrations placed on an object by previous castings of imprint message fade.","source":{"provider":"PAIZO","sourceId":"WJOQryAODgYmrL6g","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.incendiary-aura","name":"Incendiary Aura","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["aura","concentrate","fire","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself with a combustible aura. Each time a creature within the emanation takes fire damage, it catches on fire, taking (ceil(@item.level/2)+1)d4[persistent,fire] damage.\nHeightened (+2) Increase the persistent damage by 1d4 and the radius of the emanation by 5 feet.","source":{"provider":"PAIZO","sourceId":"AspA30tzKCHFWRf0","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.infectious-enthusiasm","name":"Infectious Enthusiasm","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With enchanted gusto, you encourage yourself to get things done and share your motivation with your allies. You gain a +1 status bonus to your choice of attack rolls, Will saves, or Charisma-based skill checks. During the spell's duration, an ally who observed you Casting this Spell and was within 30 feet when you did so can take a single action, which has the concentrate trait, to gain the same bonus you chose until the start of its next turn.\n\nUsing this spell to influence someone in a social situation is typically considered a faux pas, negating the benefit on Charisma-based skills if the subject of the check observed you casting the spell.","source":{"provider":"PAIZO","sourceId":"VACvA5VRbddjt5s9","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.information-overload","name":"Information Overload","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cantrip","concentrate","hex","mental","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call on Cobyslarni to open the target's mind to knowledge—too much knowledge. The target's thoughts flood with irrelevant and confusing information, causing it to become Stupefied 1 if it fails a Will save (or Stupefied 2 on a critical failure).","source":{"provider":"PAIZO","sourceId":"PesUKf0lIt5zRofj","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.infuse-vitality","name":"Infuse Vitality","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","vitality"],"traditions":["DIVINE"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 to 3 willing creatures","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You empower attacks with vital energy. The number of targets is equal to the number of actions you spent casting this spell. Each target's unarmed and weapon Strikes deal an extra 1d4 vitality damage. (This damage typically damages only undead). If you have the holy trait, you can add that trait to this spell and to the Strikes affected by the spell.\n\nHeightened (3rd) The damage increases to 2d4 damage.\n\nHeightened (5th) The damage increases to 3d4 damage.","source":{"provider":"PAIZO","sourceId":"2iQKhCQBijhj5Rf3","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.inkshot","name":"Inkshot","kind":"SPELL","rank":1,"rarity":"RARE","traits":["attack","concentrate","manipulate","poison"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"Mk0Ianq2Zs3VT6IK","formula":"2d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Mk0Ianq2Zs3VT6IK":"2d6"}},"counteraction":false,"ritual":null,"description":"A spray of viscous, toxic ink jets from your fingertip to strike a target creature in the face. Make a spell attack roll against the target. On a hit, you deal 2d6 poison damage, plus you blast the target's eyes, making them for 1 round as the stinging ink blurs and distorts the creature's vision. On a critical hit, double the poison damage, and the target becomes dazzled for 1 minute by the foul ink.\n\nThe ink stain remains for 1 hour before fading, although vigorous cleansing (or magic such as a prestidigitation cantrip) can remove the ink before then.\n\nHeightened (+1) Increase the base poison damage by 2d6.","source":{"provider":"PAIZO","sourceId":"MiTFNcqCI9f34A2V","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.inner-upheaval","name":"Inner Upheaval","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":4,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You focus your qi into devastating magical attacks. Make an unarmed Strike or (this doesn't change the limit on using only one flourish per turn). You gain a +1 status bonus to your attack rolls with the Strikes, and the Strikes deal 1d6 extra damage. This damage can be any of the following types of your choice, chosen each time you Strike: force, spirit, vitality, or void.\n\nHeightened (+4) The extra damage increases by 1d6","source":{"provider":"PAIZO","sourceId":"ZL8NTvB22NeEWhVG","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.inside-ropes","name":"Inside Ropes","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pull a large handful of guts from your midsection. Removing these guts doesn't harm you. You can use the guts as 50 feet of rope to help you , and they help attach you to a wall. You move half as quickly as usual while climbing with your guts (minimum 5 feet), but you can attempt a flat check whenever you critically fail to prevent a fall. Other creatures can use your guts to climb like a squishy rope, but the guts don't help anyone but you attach to a wall. If you let go of your guts or your guts are damaged, the spell ends.\nHeightened (3rd) You gain a +1 item bonus to Athletics checks to Climb while using your guts.","source":{"provider":"PAIZO","sourceId":"Einy9RNTGVq1kY3j","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.instant-pottery","name":"Instant Pottery","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pull earthen material out of the environment, then shape it into one or more earthenware objects that, in combination, can be up to light Bulk. Alternatively, you can cast this spell on objects previously created with this spell, extending their duration. No object can have intricate artistry or complex moving parts, can fulfill a cost or the like, or is made of anything more than clay or earth. Each object is obviously the product of temporary magic and thus can't be sold or passed off as a valuable item.\n\nHeightened (2nd) You can create objects of up to 1 Bulk. They last 8 hours.\n\nHeightened (3rd) You can create objects of up to 2 Bulk. They last 24 hours.","source":{"provider":"PAIZO","sourceId":"ET2BYfeNaHqfZIWs","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.interposing-earth","name":"Interposing Earth","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are the target of a Strike or would attempt a Reflex save against a damaging area effect.\n\nYou raise a flimsy barrier of earth to shield you from harm. This barrier is 1 inch thick, 5 feet long, 5 feet high, and must be placed on the border between two squares. This barrier appears between you and the source of the triggering effect and grants you standard cover against the triggering effect. If you would be damaged by the triggering effect despite this barrier, the barrier is destroyed, and the damage dealt to you is reduced by 2. The barrier remains in place for 3 rounds (or until destroyed). It has AC 5, 2 Hardness, and 5 Hit Points.\n\nHeightened (4th) The damage reduced increases to 8, the barrier's hardness increases to 8, and the barrier's Hit Points increases to 20.","source":{"provider":"PAIZO","sourceId":"HokKyQl5g655xx9U","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.invisible-item","name":"Invisible Item","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make the object . This makes it to all creatures, though the creatures can attempt to find the target, making it to them instead if they succeed. If the item is used as part of a hostile action, the spell ends after that hostile action is completed. Making a weapon invisible typically doesn't give any advantage to the attack, except that an invisible thrown weapon or piece of ammunition can be used for an attack without necessarily giving information about the attacker's hiding place unless the weapon returns to the attacker.\nHeightened (3rd) The duration is until the next time you make your daily preparations.\n\nHeightened (7th) The duration is unlimited.","source":{"provider":"PAIZO","sourceId":"nX85Brzax9f650aK","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.invoke-true-name","name":"Invoke True Name","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cantrip","concentrate","true-name"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature whose true name you know","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You speak the true name of a creature to more surely affect it with your magic. Until the end of the current turn, the target is against your spells and takes a -2 circumstance penalty to saving throws against your spells. In addition, the first time this turn the target takes damage from one of your spells, it has weakness to that damage equal to double the rank of invoke true name.","source":{"provider":"PAIZO","sourceId":"09C2wvWZLCxwjINk","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.item-facade","name":"Item Facade","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object no more than 10 feet by 10 feet by 10 feet","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make the target object look and feel as though it were in much better or worse physical condition. When you cast this spell, decide whether you want to make the object look decrepit or perfect. An item made to look decrepit appears and shoddy. An intact item made to look better appears as though it's brand new and highly polished or well maintained. A Broken item appears to be intact and functional. Destroyed items can't be affected by this spell. A creature that Interacts with the item can attempt to disbelieve the illusion.\n\nHeightened (2nd) The duration is 24 hours.\n\nHeightened (3rd) The duration is unlimited.","source":{"provider":"PAIZO","sourceId":"4ZGte0i9YbLh4dRi","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.jealous-hex","name":"Jealous Hex","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","curse","focus","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw forth a hag's innate jealousy to deny a target its greatest attribute. The target is cursed with an adverse condition depending on its highest attribute modifier: Strength (); Dexterity (); Constitution (); or Intelligence, Wisdom, or Charisma (). On a tie, the creature decides which of the conditions associated with the tied attributes to take. The target must attempt a Will save. At the start of each of your turns, the target can attempt another Will save, ending the effect on a success.\nSuccess The target is unaffected.\n\nFailure The condition's value is 1.\n\nCritical Failure The condition's value is 2","source":{"provider":"PAIZO","sourceId":"kvm68hVtmADiIvN4","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.join-pasts","name":"Join Pasts","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"2 willing creatures","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With touches to the targets' foreheads, you bring them into mental communion. The targets can share thoughts and experiences, but not words. When one target attempts to Recall Knowledge, the other can Aid the first target's skill check, using any Lore skill (even if that Lore wouldn't normally apply) without having made any preparations to Aid.\n\nHeightened (+1) You can touch one additional target t include them in the spell's effects. Multiple targets can attempt checks to Aid the target who is attempting to Recall Knowledge.","source":{"provider":"PAIZO","sourceId":"8bdt1TvNKzsCu9Ct","book":"Pathfinder #147: Tomorrow Must Burn","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.jump","name":"Jump","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["manipulate","move"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your legs surge with strength, ready to leap high and far. You jump 30 feet in any direction without touching the ground. You must land on a space of solid ground within 30 feet of you, or else you fall after using your next action.\n\nHeightened (3rd) The range becomes touch, the target changes to one touched creature, and the duration becomes 1 minute, allowing the target to jump as described whenever it takes the action.","source":{"provider":"PAIZO","sourceId":"Q7QQ91vQtyi1Ux36","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.juvenile-companion","name":"Juvenile Companion","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"your companion","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform your companion into its juvenile form, such as a cub, foal, kitten, puppy, or piglet, making the target appear harmless. It becomes Tiny (if it was larger), and its reach is reduced to 0 feet. All of its Speeds are halved (to a minimum Speed of 5 feet), and it gains weakness 5 to physical damage. In all other ways, its abilities and statistics are unchanged.\n\nIf your companion uses a hostile action, juvenile companion ends. This spell has no effect on a companion that doesn't have a juvenile form.\n\nHeightened (2nd) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"KFpBT6FPfSFhxQ27","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.keen-smell","name":"Keen Smell","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","morph","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your nose becomes more sensitive to the scents of the wild, the better for you to track your quarry. For the spell's duration, you gain scent as an imprecise sense with a range of 30 feet. Your hunted prey can't be undetected by you as long as it's within your scent range.\n\nHeightened (3rd) Your scent range increases to 60 feet.","source":{"provider":"PAIZO","sourceId":"SXmEI4kVWVSagK4H","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.kinetic-ram","name":"Kinetic Ram","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","force"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"target":"1 or more creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Gathering kinetic energy, you either focus it in a straight line or disperse it as an encircling ripple. Any creature targeted by this spell must succeed at a Fortitude saving throw or be pushed 10 feet away from you (or 20 feet on a critical failure).\n\nThe spell's area or range and how many creatures it affects is based on how many actions you spend when Casting the Spell.\n1 The spell targets one creature within 15 feet.\n\n2 The spell targets one creature within 30 feet. The distance the target is pushed if it fails is doubled, and on a critical failure, the target is also knocked and takes 1d6[bludgeoning] damage.\n\n3 The spell targets all creatures in a .","source":{"provider":"PAIZO","sourceId":"sPHcuLIKj9SDaDAD","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.know-location","name":"Know Location","kind":"SPELL","rank":1,"rarity":"RARE","traits":["concentrate","detection","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create an invisible anchor at a location within range (even if it's outside your line of sight or line of effect), as long as you can identify the location by its appearance (or other identifying features). You innately know the direction towards that location, including relative depth, but not the distance. Incorrect knowledge of the location's appearance usually causes the spell to fail, but it could instead lead to an unwanted location or some other unusual mishap determined by the GM. This spell doesn't help you find a suitable route to the location nor assist you in overcoming obstacles on the way there.\n\nHeightened (3rd) The range is 10 miles.\n\nHeightened (5th) The range is 100 miles.\n\nHeightened (7th) The range is planetary and you can create an anchor at a location you've viewed with scrying or similar effects.","source":{"provider":"PAIZO","sourceId":"L6kr9AUZ8iwuxIip","book":"Pathfinder #194: Cult of the Cave Worm","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.know-the-way","name":"Know the Way","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","detection","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"In your mind's eye, you magically reorient yourself. You immediately know which direction is north (if it exists at your current location), and you can choose a location you were at within the last 24 hours and learn what direction it lies.\n\nHeightened (3rd) You can choose a location you were at within the last week.\n\nHeightened (7th) You can choose a location you were at regardless of how long ago you were there.","source":{"provider":"PAIZO","sourceId":"tXa5vOu5giBNCjdR","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lament","name":"Lament","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["auditory","cleric","concentrate","emotion","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"30-foot cone"},"target":"1 or more creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"1d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You let out your negative emotions in a guttural wail that shakes your enemies' hearts and deals 1d8 mental damage (basic Will save) to each creature in the area. If you have any harmful conditions imposed by emotion effects, lament deals additional mental damage equal to the counteract rank of the highest-level effect.\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"T90ij2uu6ZaBaSXV","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.lay-on-hands","name":"Lay on Hands","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["champion","focus","healing","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing living creature or 1 undead creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your hands become infused with powerful vitality, capable of healing a living creature or damaging an undead creature with a touch.\n- Willing Living Creature The target regains 6 Hit Points. If the target is someone other than yourself, it also gains a +2 status bonus to AC for 1 round.\n- Undead Creature The target takes 1d6 vitality damage with a basic Fortitude save; on a failure, the target also takes a –2 status penalty to AC for 1 round.\nHeightened (+1) The amount of healing increases by 6, and the damage to an undead target increases by 1d6.","source":{"provider":"PAIZO","sourceId":"zNN9212H2FGfM7VS","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.leaden-steps","name":"Leaden Steps","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","metal","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You partially transform a foe's feet into unwieldy slabs of metal, slowing their steps. The target attempts a Fortitude saving throw.\nCritical Success The target is unaffected.\n\nSuccess The target is and has weakness 2 to electricity until the end of your next turn. The spell can't be sustained.\n\nFailure The target is encumbered and has weakness 2 to electricity.\n\nCritical Failure The target is encumbered and has weakness 3 to electricity.\n\nHeightened (+1) The weakness increases by 1.","source":{"provider":"PAIZO","sourceId":"2tHYKoVc5YhSewDO","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.liberating-command","name":"Liberating Command","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call out a liberating cry, urging an ally to break free of an effect that holds them in place. If the target is , , or , it can immediately use a reaction to attempt to [[/act escape]].","source":{"provider":"PAIZO","sourceId":"0Dcd4iEXqCrkm4Jn","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.life-boost","name":"Life Boost","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","healing","hex","manipulate","vitality","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"4 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Life force from your patron floods into the target, ensuring they can continue doing your patron's will for just a little longer. The target gains fast healing 2.\n\nHeightened (+1) The fast healing increases by 2.","source":{"provider":"PAIZO","sourceId":"fAlzXtQAASaJx0mY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.life-link","name":"Life Link","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","healing","manipulate","oracle","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature other than you","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"wmKl5ucMQTyXMxz1","formula":"1d4","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You forge a connection of life energy between you and your target, distributing harm between both of you. When you first Cast the Spell, the target recovers 1d4 Hit Points.\n\nThe first time each round that the target takes damage, reduce the damage it takes by 3 (to a minimum of 0 damage). You lose 3 Hit Points each time, or the total damage dealt, if less than 3; this damage ignores any immunities or resistances you have and can't otherwise be mitigated in any way.\n\nThe spell ends immediately if you fall . You can Dismiss the spell.\nHeightened (3rd) You can target 2 creatures other than you. The initial healing increases to 3d4 Hit Points and the maximum damage reduced and Hit Points lost increases to 5.\n\nHeightened (6th) You can target 3 creatures other than you. The initial healing increases to 6d4 Hit Points and the maximum damage reduced and Hit Points lost increases to 10.\n\nHeightened (9th) You can target 4 creatures other than you. The initial healing increases to 9d4 Hit Points and the maximum damage reduced and Hit Points lost increases to 15.","source":{"provider":"PAIZO","sourceId":"2gQYrCPwBmwau26O","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.lift-natures-caul","name":"Lift Nature's Caul","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","fear","focus","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a wave of the hand, you cause all creatures in the area to see the world around them as if a gauzy film had been lifted away to expose the truth that lies below their perceived reality. Natural features they can see grow twisted and horrendous, structures appear distorted and ruined, and objects seem warped and alien. This alternate vision fades quickly, but the glimpse beyond the natural world lingers for the spell's duration.\n\nAberrations or worshippers of Outer Gods or Great Old Ones are bolstered by this vision of warped reality and gain a +1 status bonus to Will saving throws and attack rolls for 1 minute, while all other creatures must attempt a Will saving throw.\n\nCritical Success The creature is unaffected and temporarily immune for 1 hour.\n\nSuccess The creature is Sickened 1.\n\nFailure The creature is Stupefied 1 for 1 minute and Frightened 1.\n\nCritical Failure The creature is stupefied 1 for 1 minute and Frightened 2. It can't reduce the value of its frightened condition below 1 as long as it remains stupefied by this spell.\nHeightened (+2) The area increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"6GjJtLJnwC18Y0aZ","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.light","name":"Light","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","light","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an orb of light that sheds bright light in a 20-foot radius (and dim light for the next 20 feet) in a color you choose. If you create the light in the same space as a willing creature, you can attach the light to the creature, causing it to float near that creature as it moves. You can Sustain the spell to move the light up to 60 feet; you can attach or detach it from a creature as part of this movement.\n\nYou can Dismiss the spell. If you Cast the Spell while you already have four light spells active, you must choose one of the existing spells to end.\n\nHeightened (4th) The orb sheds light in a 60-foot radius (and dim light for the next 60 feet).","source":{"provider":"PAIZO","sourceId":"WBmvzNDfpwka3qT4","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lingering-composition","name":"Lingering Composition","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["bard","concentrate","focus","spellshape"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You add a flourish to your composition to extend its benefits. If your next action is to cast a cantrip composition with a duration of 1 round, attempt a performance check. The DC is usually a standard-difficulty DC of a level equal to the highest-level target of your composition, but the GM can assign a different DC based on the circumstances. The effect depends on the result of your check.\n\nCritical Success The composition lasts 4 rounds.\n\nSuccess The composition lasts 3 rounds.\n\nFailure The composition lasts 1 round, but you don't spend the Focus Point for casting this spell.","source":{"provider":"PAIZO","sourceId":"irTdhxTixU9u9YUm","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.live-wire","name":"Live Wire","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","cantrip","concentrate","electricity","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"6jB29A0HYmZ5Sndk","formula":"1d4","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"u8FtIoasOdjfSdy4","formula":"1d4","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"6jB29A0HYmZ5Sndk":"1d4","u8FtIoasOdjfSdy4":"1d4"}},"counteraction":false,"ritual":null,"description":"You conjure up a length of sharp copper filament humming with electrical current that strikes out at your foe. The wire deals 1d4 slashing damage and 1d4 electricity damage, depending on your spell attack roll against the target's AC.\nCritical Success The target takes double damage and (ceil(@item.rank / 2))d4[persistent,electricity] damage.\n\nSuccess The target takes full damage.\n\nFailure The target takes the electricity damage, but not the slashing damage.\n\nCritical Failure The target is unaffected.\nHeightened (+2) The slashing damage, initial electricity damage, and persistent electricity damage on a critical hit each increase by 1d4.","source":{"provider":"PAIZO","sourceId":"Vbj8bTQ1nwrOBbYF","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.lock","name":"Lock","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 lock, or a door or container with a latch","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's latch mechanism clinks shut, held fast by unseen magical wards. When you magically lock a target, you set an Athletics and Thievery DC to open it equal to your spell DC or the base lock DC with a +4 status bonus, whichever is higher. Any key or combination that once opened a lock affected by this spell does not do so for the duration of the spell, though the key or combination does grant a +4 circumstance bonus to checks to open the door. If the target is opened, the spell ends. Assuming the target is not barred or locked in some additional way, you can unlock and open it with an Interact action during which you touch the target. This does not end the spell. You can Dismiss this spell at any time and from any distance.\n\nHeightened (2nd) The duration is unlimited, but you must expend 6 gp worth of precious metals as an additional cost.","source":{"provider":"PAIZO","sourceId":"Azoh0BSoCASrA1lr","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.loremasters-etude","name":"Loremaster's Etude","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["bard","composition","focus","fortune","manipulate"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you or the triggering ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or an ally within range attempts a skill check to Recall Knowledge\n\nYou call upon your muse's deep mysteries, granting the target a greater ability to think and recall information. Roll the triggering Recall Knowledge skill check twice and use the higher result.","source":{"provider":"PAIZO","sourceId":"5Pc55FGGqVpIAJ62","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lose-the-path","name":"Lose the Path","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["illusion","manipulate","mental","visual"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature in range Strides\n\nYou surround a moving creature with lifelike illusions, shifting their perception of the terrain to subtly lead them off course. The target must attempt a Will save. Regardless of the result, the creature is immune to lose the path for 1 hour.\n\nSuccess The creature is unaffected.\n\nFailure The creature treats all squares as difficult terrain for its Stride.\n\nCritical Failure As failure, except that you determine where the target moves during the Stride, though you can't move it into hazardous terrain or to a place it can't stand.","source":{"provider":"PAIZO","sourceId":"iohRnd4gUCmJlh54","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magic-hide","name":"Magic Hide","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","manipulate","ranger"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your animal companion","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your animal companion grows a thicker hide, matted fur, or a harder shell, granting it a +1 status bonus to AC.","source":{"provider":"PAIZO","sourceId":"u2uSeH6YSbK1ajTy","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magic-stone","name":"Magic Stone","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 to 3 non-magical stones or sling bullets","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pour vitality energy into ordinary stones, granting them temporary magical properties. You can target 1 non-magical stone or sling bullet for every action you use Casting this Spell. The stones must be unattended or carried by you or a willing ally. The stones become +1 striking disrupting . Each stone can be used only once, after which it crumbles to dust.","source":{"provider":"PAIZO","sourceId":"9u6X9ykhzG11NK1n","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.magics-vessel","name":"Magic's Vessel","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A creature becomes a divine receptacle for pure magical energy. The target gains a +1 status bonus to saving throws. Each time you Cast a Spell from your spell slots, you automatically Sustain this spell and grant its target resistance to damage from spells equal to the spell's rank, until the start of your next turn.","source":{"provider":"PAIZO","sourceId":"u4FGIUQgruLjml7J","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.malediction","name":"Malediction","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["aura","concentrate","manipulate","mental"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You incite distress in the minds of your enemies, making it more difficult for them to defend themselves. Enemies in the area must succeed at a Will save or take a –1 status penalty to AC as long as they're in the area.\n\nOnce per round on subsequent turns, you can Sustain the spell to increase the emanation's radius by 10 feet and force enemies in the area that weren't yet affected to attempt a saving throw.\n\nMalediction can counteract benediction.","source":{"provider":"PAIZO","sourceId":"AdZ2rWJStZ5unxzq","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.manifest-will","name":"Manifest Will","kind":"SPELL","rank":1,"rarity":"RARE","traits":["aura","cantrip","concentrate","hex","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You unleash energy from the broken connection to your patron. You are from creatures beyond the edge of the emanation but can't use that concealment to . Any creature that begins its turn in the emanation is affected based on your patron's tradition.\n\n- Arcane Raw energy and magical formulae circulate around you. A creature that begins its turn in the emanation gains weakness 1 to spell damage for 1 round.\n- Divine Divine power crashes in a cycle of life and death. A living or undead creature that begins its turn in the emanation gains 2 temporary Hit Points for 1 round. This effect has the spirit trait.\n- Occult Esoteric symbology etches the air. An allied creature that begins its turn in the emanation has Lesser Cover while inside the emanation, and for 1 round after it leaves.\n- Primal Plants and fungus symbolic of your patron constantly grow and wither in the emanation. A creature that begins its turn in the emanation has a –10-foot status penalty to all its Speeds for 1 round or until it Escapes. This effect has the fungus, plant, and wood traits.\n\nHeightened (+1) An arcane manifestation increases its weakness by 1 and a divine manifestation increases its temporary Hit Points by 2.","source":{"provider":"PAIZO","sourceId":"IqBfoUaWDennHYoZ","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mending","name":"Mending","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"non-magical object of light Bulk or less","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You repair the target item. You restore 5 Hit Points per spell rank to the target, potentially removing the condition if this repairs it past the item's Broken Threshold. You can't replace lost pieces or repair an object that's been completely destroyed.\n\nHeightened (2nd) You can target a non-magical object of 1 Bulk or less.\n\nHeightened (3rd) You can target a non-magical object of 2 Bulk or less, or a magical object of 1 Bulk or less.","source":{"provider":"PAIZO","sourceId":"dINQzhqGmIsqGMUY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.message","name":"Message","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","cantrip","concentrate","illusion","linguistic","mental","subtle"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"see below","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You mouth words quietly, but instead of coming out of your mouth, they're transferred directly to the ears of the target. While others can't hear your words any better than if you normally mouthed them, the target can hear your words as if they were standing next to you. The target can give a brief response as a reaction, or as a free action on their next turn if they wish, but they must be able to see you and be within range to do so. If they respond, their response is delivered directly to your ear, just like the original message.\n\nHeightened (3rd) The spell's range increases to 500 feet.","source":{"provider":"PAIZO","sourceId":"vLzFcIaSXs7YTIqJ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.message-rune","name":"Message Rune","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","linguistic","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"5 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 flat unattended surface or non-magical object of light Bulk","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You record a message up to 5 minutes long and inscribe a special rune on any flat unattended surface or small object within reach. The nature of the rune's appearance is up to you, but it's visible to everyone, and it must be no smaller than 2 inches in diameter. You also specify a trigger that creatures must meet to activate the rune.\n\nFor the duration of the spell, creatures that meet the criteria of the trigger can touch the rune to hear the recorded message in their head as though you were speaking to them telepathically. You know when someone is listening to the message, but you don't know who's listening to it. You can Dismiss the spell.\nHeightened (+2) The duration increases for every 2 ranks, becoming 1 week, 1 month, 1 year, or unlimited respectively.","source":{"provider":"PAIZO","sourceId":"Z7N5IxJCwrAdIgSg","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mindlink","name":"Mindlink","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You link your mind to the target's mind and mentally impart to that target an amount of information in an instant that could otherwise be communicated in 10 minutes.","source":{"provider":"PAIZO","sourceId":"D442XMADp01qJ7Cs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.moonbeam","name":"Moonbeam","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cleric","concentrate","fire","focus","light","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You shine a ray of moonlight. Make a spell attack roll. The beam of light deals 2d6 fire damage. This is silver damage for the purposes of weaknesses, resistances, and the like.\n\nCritical Success The beam deals double damage, and the target is for 1 minute.\n\nSuccess The beam deals full damage, and the target is Dazzled for 1 round.\n\nHeightened (+1) The ray's damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"SuBtUJiU6DbSJYIw","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.mud-pit","name":"Mud Pit","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","earth","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Thick, clinging mud covers the ground, 1 foot deep. The mud is difficult terrain.","source":{"provider":"PAIZO","sourceId":"yAiSNmz39qXOIlco","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.murmuration","name":"Murmuration","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","hex","sonic","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target feels the brush of feathers against its skin and hears screeches in its ears, warning it to keep away from a creature you designate that's within 30 feet of you when you Cast this Spell (which can include yourself). Once per round, if the target moves closer to the designated creature, it must attempt a Will save or take (@item.rank)d4[piercing] or (@item.rank)d4[sonic] damage.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage.\n\nCritical Failure The target takes (@item.rank)d4[sonic,(@item.rank)d4[piercing]] damage, and if it attempts an attack roll or hostile skill check this round, it takes a –2 status penalty to the roll.\n\nHeightened (+1) The damage increases by 1d4, or by 2d4 on a critical failure (1d4 of which is sonic and 1d4 of which is piercing).","source":{"provider":"PAIZO","sourceId":"4EmLum6EdvXxbxCj","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mushroom-patch","name":"Mushroom Patch","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","druid","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You cause mushrooms to sprout in the area. The area becomes difficult terrain. When the spell is cast and at the beginning of each round, the mushroom's release a cloud of irritating spores. Creatures in the area must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is for 1 round. If the creature moves to outside area, they can spend 1 action to rub their eyes, removing the dazzled condition.\n\nFailure The creature becomes dazzled for 1 round.\n\nCritical Failure The creature becomes dazzled and Slowed 1 for 1 round.\n\nHeightened (3rd) The range increases to 90 feet and the area increases to a 20-foot-radius burst.\n\nHeightened (6th) The range increases to 120 feet and the area increases to a 30-foot-radius burst.\n\nHeightened (9th) The range increases to 150 feet, the area increases to a 40-foot-radius burst, and when a creature would become dazzled, they become instead.","source":{"provider":"PAIZO","sourceId":"xCfOskoogDf9LBlD","book":"Pathfinder #202: Severed at the Root","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.musical-accompaniment","name":"Musical Accompaniment","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","cantrip","concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You're surrounded by orchestral music that shifts and changes to match your behavior. This music provides a +1 status bonus to Performance checks. At the GM's discretion, it provides this bonus to Deception, Diplomacy, and Intimidation checks as the music changes to support you in social situations, though some creatures are unaffected by such obvious attempts to use music to illicit specific emotions. This music moves with you and has a maximum volume equal to four humans shouting. You take a -4 penalty to Stealth checks while the music is playing. You can't control the exact music this spell creates. The music doesn't create intelligible words or singing. You can Dismiss this spell.\n\nHeightened (2nd) The duration increases to 10 minutes.","source":{"provider":"PAIZO","sourceId":"mnhuvqTIELcpJOFX","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mystic-armor","name":"Mystic Armor","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ward yourself with shimmering magical energy, gaining a +1 item bonus to AC and a maximum Dexterity modifier of +5. While wearing mystic armor, you use your unarmored proficiency to calculate your AC.\n\nHeightened (4th) You gain a +1 item bonus to saving throws.\n\nHeightened (6th) The item bonus to AC increases to +2, and you gain a +1 item bonus to saving throws.\n\nHeightened (8th) The item bonus to AC increases to +2, and you gain a +2 item bonus to saving throws.\n\nHeightened (10th) The item bonus to AC increases to +3, and you gain a +3 item bonus to saving throws.","source":{"provider":"PAIZO","sourceId":"aAbfKn8maGjJjk2W","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.necromancers-generosity","name":"Necromancer's Generosity","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 undead minion you control","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8+4","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8+4"}},"counteraction":false,"ritual":null,"description":"You channel void energy through your magical connection to your undead minion to strengthen the creature. The target regains 1d8+4 Hit Points when you Cast the Spell, and it gains a +2 status bonus to saves against vitality effects for the duration.\n\nHeightened (+1) The amount of healing increases by 1d8+4.","source":{"provider":"PAIZO","sourceId":"JUJYVbtNNFdvyrBS","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.needle-darts","name":"Needle Darts","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","cantrip","concentrate","manipulate","metal"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"71hLuboTBYkwkqiR","formula":"3d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"71hLuboTBYkwkqiR":"1d4"}},"counteraction":false,"ritual":null,"description":"You shape three needles out of a piece of metal in your possession and send them flying in a tight group toward one target. Make a spell attack roll against your target's AC. The needles deal 3d4 piercing damage and might cause bleeding.\n\nThe needles impart any special properties of the metal that forms them; for instance, cold iron needles deal additional damage to creatures with weakness to cold iron. All the needles are made of the same metal, and the metal returns to you after the attack.\nCritical Success The target takes double damage and (@item.level)[bleed] damage.\n\nSuccess The target takes full damage.\nHeightened (+1) You send one additional needle, increasing the regular damage by 1d4 and increasing the persistent bleed damage on a critical hit by 1.","source":{"provider":"PAIZO","sourceId":"iYRDFxeVpJ5KIjmr","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.needle-of-vengeance","name":"Needle of Vengeance","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","hex","manipulate","mental","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 enemy","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"2","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2"}},"counteraction":false,"ritual":null,"description":"A long, jagged needle jabs into the target foe's psyche whenever it tries to attack a creature your patron holds in special regard. Name yourself or one of your allies. The target takes 2 mental damage any time it uses a hostile action against the named creature, with a basic Will save.\nHeightened (+1) Increase the damage by 2.","source":{"provider":"PAIZO","sourceId":"aEitTTb9PnOyidRf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.negate-aroma","name":"Negate Aroma","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target loses its odor, preventing creatures from passively noticing its presence via smell alone, even if the creatures have precise or imprecise scent. A creature attempting a Perception check to Seek with scent and other senses might notice the lack of natural scent. If the target has any abilities that result from its smell, such as an overpowering scent, those abilities are also negated.\n\nHeightened (5th) The range increases to 30 feet, and you can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"0fKHBh5goe2eiFYL","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nettleskin","name":"Nettleskin","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","manipulate","plant"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"SELF"},"target":"self","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"u1tz6yrszljlkr1m","formula":"1d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"u1tz6yrszljlkr1m":"1d4"}},"counteraction":false,"ritual":null,"description":"Thorns sprout from your body; they pass through and don't damage any clothing or armor you wear.\n\nAdjacent creatures that hit you with a melee or unarmed attack take 1d4 piercing damage as the nettles jab them and break off. Each time a creature takes damage in this way, nettleskin's duration decreases by 1 round.\n\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"BA143r8fCqmSjdRf","book":"Pathfinder Adventure: Threshold of Knowledge","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.noxious-vapors","name":"Noxious Vapors","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You emit a cloud of toxic smoke that temporarily obscures you from sight. Each creature except you in the area when you Cast the Spell takes 1d6 poison damage (basic Fortitude save). A creature that critically fails the saving throw also becomes Sickened 1. All creatures in the area become , and all creatures outside the smoke become concealed to creatures within it. This smoke can be dispersed by a strong wind.\nHeightened (+1) The damage increases by 1d6","source":{"provider":"PAIZO","sourceId":"1meVElIu1CEVYWkv","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.nudge-fate","name":"Nudge Fate","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","hex","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The barest spin of your patron's spool is enough to alter fate. When the target fails an attack roll, skill check, or saving throw and a +1 status bonus would turn a critical failure into a failure, or failure into a success, you grant the target a +1 status bonus to the check retroactively, changing the outcome appropriately. The spell then ends.\n\nIf you cast nudge fate while a previous casting of this hex is still in effect, the previous effect ends","source":{"provider":"PAIZO","sourceId":"G0T1xv1FoZ23Jxvt","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nudge-the-odds","name":"Nudge the Odds","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bestow yourself supernaturally good luck at cards, dice, and other games of chance. You gain a +1 status bonus to Games Lore checks to gamble, and if you roll a critical failure on such a check, you get a failure instead; however, the spell is too short-lived to use for Earn Income checks from gambling.\n\nWhen you're under the effect of nudge the odds, one facial feature, such as a lock of hair or the iris of an eye, transforms to a distinctive golden color; the GM chooses which feature when you cast the spell. This change resists all magical efforts to conceal it, though it can be hidden or covered by mundane means. A creature noticing the feature can identify the spell using Recall Knowledge. Because it prevents losing big, gamblers consider nudge the odds a repugnant form of cheating. If you're caught using the spell, you are likely to suffer serious consequences, depending on the nature of the gamblers you cheated.\n\nHeightened (5th) The status bonus increases to +2, and the duration increases to last until the next time you make your daily preparations. If you continue spending your spell slot to keep the duration active, this allows you to apply the effect to a downtime check to Earn Income.","source":{"provider":"PAIZO","sourceId":"QjdvYC1QkpMaemoX","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nymphs-grace","name":"Nymph's Grace","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","aura","emotion","focus","incapacitation","mental","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your apparition manifests as a mask of unearthly beauty that bewilders your enemies. The first time an enemy enters the aura each round, or if they start their turn within the aura, they must succeed at a Will saving throw or become for 1 round. While confused by this effect, the creature's confused actions never include harming you.","source":{"provider":"PAIZO","sourceId":"SAmyaiVKTDrUNjot","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.nymphs-token","name":"Nymph's Token","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant an ally a token of favor. You create a token, such as a lock of your hair or a flower, that persists for the spell's duration; as part of Casting the Spell, you can to pass the token to an ally within your reach.\n\nAs long as the ally has the token on their person, they gain a +1 status bonus to Performance checks and Will saves.\n\nYou can the spell as a free action.\n\nHeightened (4th) As long as the ally has the token on their person, you can cast spells that have a range of touch on them at a range of 30 feet.","source":{"provider":"PAIZO","sourceId":"pHrVvoTKygXeczVG","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.oathkeepers-insignia","name":"Oathkeeper's Insignia","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You make a promise or deal.\n\nA magical indicator assures a creature that you've upheld your end of a bargain. When you Cast the Spell, you create a bracelet, flower, or other such trinket. If, while the spell persists, you complete the terms of the promise or deal you made, the trinket fades away with a pleasant chime; if you violate the terms instead, the trinket breaks with a dissonant crash.\n\nHeightened (3rd) The duration becomes 1 day.\n\nHeightened (5th) The duration becomes 1 week.\n\nHeightened (7th) The duration becomes 1 month.\n\nHeightened (9th) The duration becomes 1 year.","source":{"provider":"PAIZO","sourceId":"cokeXkDHUAo4zHsw","book":"Pathfinder Lost Omens Gods & Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.object-memory","name":"Object Memory","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"1 weapon or tool","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"By touching an object, you draw forth the experience of those who created and used it. If you touch a weapon, your proficiency rank with that weapon temporarily increases to trained (if it is not already trained or better). If you touch a tool, your proficiency rank with the next skill check you attempt with that tool (such as a Crafting check with a blacksmith's hammer) within the spell's duration temporarily increases to trained (if it is not already trained or better). This spell has no benefit for activities that take longer than a minute to complete.\nHeightened (6th) Your proficiency rank increases to expert instead of trained.","source":{"provider":"PAIZO","sourceId":"RztmhJrLLQWoGVdB","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.object-reading","name":"Object Reading","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You place a hand on an object to learn a piece of information about an emotional event that occurred involving the object within the past week, determined by the GM. If you cast object reading on the same item multiple times, you can either concentrate on a single event to gain additional pieces of information about that event, or you can gain a piece of information about another emotional event in the applicable time frame.\n\nHeightened (2nd) You can learn about an event that occurred within the last month.\n\nHeightened (4th) You can learn about an event that occurred within the last year.\n\nHeightened (6th) You can learn about an event that occurred within the last decade.\n\nHeightened (8th) You can learn about an event that occurred within the last century.\n\nHeightened (9th) You can learn about an event that occurred within the entirety of the object's history.","source":{"provider":"PAIZO","sourceId":"5LYi9Efs6cko4GGL","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.overselling-flourish","name":"Overselling Flourish","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature damages you.\n\nYou make a grand spectacle out of getting hit. Enhanced by magic, this spectacle features sprays of blood, anguished screams, or other theatrics that appear to result from your foe's attack. The triggering creature must attempt a Will saving throw.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is thrown off by your display. The creature becomes until the start of your turn.\n\nFailure The creature fully believes your performance, leaving itself open. The creature becomes dazzled and until the start of your turn.\n\nCritical Failure The creature is enraptured by the display. The creature uses its remaining actions to watch you in awe. It then remains dazzled and off-guard until the start of your turn.","source":{"provider":"PAIZO","sourceId":"ro0omoBKiJiMuDRa","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.overstuff","name":"Overstuff","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Huge amounts of food and drink fill the target. It receives a full meal's worth of nourishment and must attempt a Fortitude save. A target sickened by this spell takes a –10-foot status penalty to its Speed until it's no longer sickened.\nCritical Success The target is unaffected.\n\nSuccess The target is Sickened 1, but if it spends an action to end the condition, it succeeds automatically.\n\nFailure The target is sickened 1.\n\nCritical Failure The target is Sickened 2.","source":{"provider":"PAIZO","sourceId":"mFHQ2u4LWiejqKQG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pact-broker","name":"Pact Broker","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["auditory","cantrip","concentrate","hex","linguistic","mental","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"cQxR8sbsuYgdFzKD","formula":"2d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"cQxR8sbsuYgdFzKD":"1d4"}},"counteraction":false,"ritual":null,"description":"You offer to broker a pact of peace. If the target accepts and doesn't take hostile actions against you and your allies during the hex's duration, you take a –1 status penalty to Deception checks to Lie to them. If they refuse and take a hostile action against you or an ally during the hex's duration, they must first attempt a Will save. If they accepted the offer and then take a hostile action against you or an ally during the hex's duration, they must first attempt a Will save and treat the result as one category worse. Regardless of the outcome, the target is then temporarily immune for 1 minute.\n\nSuccess The target is unaffected.\n\nFailure The target takes 2d4 mental damage and a –1 status penalty to attack and damage rolls against you and your allies for the hex's duration.\n\nCritical Failure As failure, but the penalty is –2.\n\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"YNAthsgsJjQIXbc8","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.parch","name":"Parch","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["air","cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Dry winds dehydrate a creature. The target must attempt a Fortitude save; if used on a creature that has the water trait or a creature made primarily of liquid (such as many oozes), the creature uses the outcome for one degree of success worse than the result. Creatures whose bodies contain no significant moisture (such as earth elementals) are immune to parch.\n\nIf a creature affected by parch drinks a liquid, such as a swig of water or a potion, the spell ends. Affected creatures that have the water trait or are made primarily of liquid, as well as affected creatures that can't drink, can end the effect as a two-action activity, which has the concentrate trait.\nCritical Success The target is unaffected.\n\nSuccess The target takes a –1 status penalty to its checks and DCs for 1 round.\n\nFailure The target takes a –1 status penalty to its checks and DCs for 1 minute.\n\nCritical Failure The target takes a –2 status penalty to its checks and DCs for 1 minute and is as long as it has this penalty.\nHeightened (4th) You can target up to 4 creatures.","source":{"provider":"PAIZO","sourceId":"7CUgqHunmHfW2lC5","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.patrons-puppet","name":"Patron's Puppet","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","hex","witch"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger Your turn begins.\n\nAt your unspoken plea, your patron temporarily assumes control over your familiar. You Command your familiar, allowing it to take its normal actions this turn. Your Command does not have the auditory or concentrate traits; your patron simply moves its agent directly.","source":{"provider":"PAIZO","sourceId":"aq1yonHeYpbaj3XI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.penumbral-shroud","name":"Penumbral Shroud","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","darkness","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You envelop the target in a shroud of shadow. The target perceives light as one step lower than it actually is (bright light becomes dim light, for example), affecting their ability to sense creatures and objects accordingly.\n\nThe shroud also provides the target a +1 status bonus to saving throws against light effects. This effect is helpful to creatures sensitive to light, and a creature can willingly choose to be subject to the failure effect of the spell.\nCritical Success The target is unaffected.\n\nSuccess The effect lasts for 1 round.\n\nFailure The effect lasts its normal duration.","source":{"provider":"PAIZO","sourceId":"zdb8cjOIDVKYMWdr","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.perfected-mind","name":"Perfected Mind","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You meditate upon perfection to remove all distractions from your mind. Attempt a new Will save against one mental effect currently affecting you that required a Will save. Use the result of this new save to determine the outcome of the mental effect, unless the new save would have a worse result than the original save, in which case nothing happens. You can use perfected mind against a given effect only once.","source":{"provider":"PAIZO","sourceId":"cDFAQN7Z3es07WSA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.personal-rain-cloud","name":"Personal Rain Cloud","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a 5-foot-wide rain cloud that follows the target wherever it goes. It stays roughly an arm's length overhead, unless it must drift lower to fit under a ceiling. The cloud rains constantly on the target, keeping it wet and dampening the ground in the wake of any movement. The rain extinguishes non-magical flames. The target gains fire resistance 2. Creatures with weakness to water take damage equal to their weakness at the end of each of their turns. Creatures can attempt a Reflex save to avoid the cloud.\n\nHeightened (+1) The amount of fire resistance increases by 2.","source":{"provider":"PAIZO","sourceId":"kJKSLfCgqxmN2FY8","book":"Pathfinder #151: The Show Must Go On","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pest-form","name":"Pest Form","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform into the battle form of a Tiny animal, such as a cat, insect, lizard, or rat. You can decide the specific type of animal (such as a rat or praying mantis), but this has no effect on the form's Size or statistics. While in this form, you gain the animal trait and you can't make Strikes. You can Dismiss the spell.\n\nYou gain the following statistics and abilities:\n\n- AC = 15 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- Speed 20 feet.\n\n- Weakness 5 to physical damage. (If you take physical damage in this form, you take 5 additional damage.)\n\n- Low-light vision and imprecise scent 30 feet.\n\n- Acrobatics and Stealth modifiers of +10, unless your own modifier is higher; Athletics modifier -4.\n\nHeightened (4th) You can turn into a flying creature, such as a bird, which grants you a fly Speed of 20 feet.","source":{"provider":"PAIZO","sourceId":"gfPjmG6Fe6D3MFjl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pet-cache","name":"Pet Cache","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["extradimensional","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature that is your companion","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You open your cloak or create a gap with your hands, drawing the target into a pocket dimension just large enough for its basic comfort. No other creature can enter this extradimensional space, and the target can bring along objects only if they were designed to be worn by a creature of its kind. The space has enough air, food, and water to sustain the target for the duration.\n\nYou can the spell. The spell also ends if you die or enter an extradimensional space. When the spell ends, the target reappears in the nearest unoccupied space (outside of any extradimensional space you may have entered).","source":{"provider":"PAIZO","sourceId":"F1nlmqOIucch3Cmt","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantasmal-minion","name":"Phantasmal Minion","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a . The minion is roughly the shape of a humanoid. You can choose to have it be or have an ephemeral appearance, but it's obviously a magical effect, not a real creature.","source":{"provider":"PAIZO","sourceId":"xqmHD8JIjak15lRk","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantom-pain","name":"Phantom Pain","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental","nonlethal"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"2d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"}},"counteraction":false,"ritual":null,"description":"Illusory pain wracks the target, dealing 2d4 mental damage and (@item.level)d4[persistent,mental] damage. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target takes full initial damage but no persistent damage, and the spell ends immediately.\n\nFailure The target takes full initial and persistent damage, and the target is Sickened 1. If the target recovers from being Sickened, the persistent damage ends and the spell ends.\n\nCritical Failure As failure, but the target is Sickened 2.\nHeightened (+1) The damage increases by 2d4 and the persistent damage by 1d4.","source":{"provider":"PAIZO","sourceId":"R8bqnYiThB6MYTxD","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.phase-bolt","name":"Phase Bolt","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","cantrip","concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"nqp6byhfcwbvtstj","formula":"3d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"nqp6byhfcwbvtstj":"1d4"}},"counteraction":false,"ritual":null,"description":"You point your finger and project a bolt of magical energy that stutters in and out of phase until it reaches the target. Make a ranged spell attack roll against your target's AC; if the target has any circumstance bonuses to AC (such as from a shield or cover), reduce that bonus by 2 for this attack. On a success, you deal 3d4 piercing damage.\nCritical Success The target takes double damage.\n\nSuccess The target takes full damage.\nHeightened (+1) The bolt's damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"5gophZ4AOKW4VW27","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.phase-familiar","name":"Phase Familiar","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"your familiar","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger Your familiar would take damage.\n\nYour patron momentarily recalls your familiar to the ether, shifting it from its solid, physical form into a ghostly version of itself. Against the triggering damage, your familiar gains resistance 5 to all damage and is immune to precision damage.\n\nHeightened (+1) Increase the resistance by 2.","source":{"provider":"PAIZO","sourceId":"rMOI8JFJ0nT2mrCF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.physical-boost","name":"Physical Boost","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"until the end of the target's next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You temporarily improve the target's physique. The target gains a +2 status bonus to the next Acrobatics check, Athletics check, Fortitude save, or Reflex save it attempts.","source":{"provider":"PAIZO","sourceId":"1lmzILdCFENln8Cy","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pocket-library","name":"Pocket Library","kind":"SPELL","rank":1,"rarity":"RARE","traits":["concentrate","extradimensional","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Like Vil Seral, you collect information from all around you and store it in book form in an extradimensional library. When you Cast this Spell, choose any skill in which you are at least trained that has the Recall Knowledge action.\n\nDuring the duration of this spell, you can call forth a tome from the extradimensional library when attempting a Recall Knowledge check using your chosen skill. This is part of the action to Recall Knowledge. You must have a hand free to do so. The tome appears in your hand, open to an appropriate page. This grants you a +1 status bonus to the Recall Knowledge check. If you roll a critical failure on this check, you get a failure instead. If the roll is successful and the subject is a creature, you gain additional information or context about the creature. Once you reference a book from your pocket library, the spell ends.\n\nHeightened (3rd) The status bonus increases to +2 and you can reference your pocket library twice before the spell ends.\n\nHeightened (6th) The status bonus increases to +3 and you can reference your pocket library three times before the spell ends.\n\nHeightened (9th) The status bonus increases to +4 and you can reference your pocket library four times before the spell ends.","source":{"provider":"PAIZO","sourceId":"TjWHgXqPv5jywMti","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.practice-makes-perfect","name":"Practice Makes Perfect","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or an ally within range fails a skill check for a skill in which you or they are trained.\nThe target gains a +2 status bonus to the triggering check, or a +3 bonus if the target has master or better proficiency in the skill. This bonus can change the outcome of the target's skill check.","source":{"provider":"PAIZO","sourceId":"HOj2YsTpkoMpYJH9","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.precious-gleam","name":"Precious Gleam","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 weapon that is unattended or wielded by a willing creature.","area":null},"duration":{"text":"until the beginning of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You temporarily enhance a weapon, replacing it with finer materials. On the next successful attack with that weapon during the spell's duration, the attack deals an additional 1d6 precision damage. You can choose for the metal to become your choice of cold iron, silver, or steel, causing the attack to bypass resistances accordingly.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"v14zLiiSc4sl9RrK","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.prestidigitation","name":"Prestidigitation","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 object (cook, lift, or tidy only)","area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The simplest magic does your bidding. You can perform simple magical effects for as long as you Sustain the spell. Each time you Sustain the spell, you can choose one of four options.\n- Cook Cool, warm, or flavor 1 pound of nonliving material.\n- Lift Slowly lift an unattended object of light Bulk or less 1 foot off the ground.\n- Make Create a temporary object of negligible Bulk, made of congealed magical substance. The object looks crude and artificial and is extremely fragile-it can't be used as a tool, weapon, or locus or cost for a spell.\n- Tidy Color, clean, or soil an object of light Bulk or less. You can affect an object of 1 Bulk with 10 rounds of concentration, and a larger object at 1 minute per Bulk.\nPrestidigitation can't deal damage or cause adverse conditions. Any actual change to an object (beyond what is noted above) persists only as long as you Sustain the spell.","source":{"provider":"PAIZO","sourceId":"Qw3fnUlaUbnn7ipC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.protect-companion","name":"Protect Companion","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your eidolon, or a creature with the minion trait under your control","area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You extend your aura, as a magical shield that protects your eidolon or minion. The target gains a +1 circumstance bonus to AC until the start of your next turn. You gain the reaction; after using the reaction, the spell ends and you can't cast protect companion again for 10 minutes.\n\nHeightened (+2) The reaction reduces the damage by another 10, and you lose 5 more Hit Points. If you want to lose fewer Hit Points, you can choose to lower the damage reduction and HP lost to what any lower-rank version of the spell could do without lowering the spell's actual rank.","source":{"provider":"PAIZO","sourceId":"AfOpnnwdZwHi2Tnc","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.protection","name":"Protection","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ward a creature against harm. The target gains a +1 status bonus to Armor Class and saving throws.\n\nHeightened (3rd) You can choose to have the benefits also affect all your allies in a around the target.","source":{"provider":"PAIZO","sourceId":"gMODOGamz88rgHuf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.protective-wards","name":"Protective Wards","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["aura","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You expand a ring of glyphs that shields your allies. You and any allies in the area gain a +1 status bonus to AC. Each time you Sustain the spell, the emanation's radius increases by 5 feet, to a maximum of 30 feet.","source":{"provider":"PAIZO","sourceId":"lY9fOk1qBDDhBT8s","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.protector-tree","name":"Protector Tree","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A Medium tree suddenly grows in an unoccupied square within range. The tree has AC 10 and 10 Hit Points. Whenever an ally adjacent to the tree is hit by a Strike, the tree interposes its branches and takes the damage first. Any additional damage beyond what it takes to reduce the tree to 0 Hit Points is dealt to the original target. The tree isn't large enough to impede movement through its square. If the tree is in soil and survives to the end of the spell's duration, it remains as an ordinary, non-magical tree and continues to grow and thrive. The GM might determine that the tree disappears immediately in certain inhospitable situations.\nHeightened (+1) The tree has an additional 10 Hit Points.","source":{"provider":"PAIZO","sourceId":"K9gI08enGtmih5X1","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
